class TimeoutError(Exception):
    pass


class NegativeOperationStatus(Exception):
    pass


class OPS(object):
    def __init__(self, api_client):
        """
        :param DefaultApi api_client:
        """
        self.api_client = api_client
        # Workaround for import_sw_package: "OverflowError: string longer than 2147483647 bytes"
        # Allow setting of file-like object as request body to avoid OOM and above exception
        # https://docs.python-requests.org/en/master/user/advanced/#streaming-uploads
        self.api_client.api_client.PRIMITIVE_TYPES += (file,)

    def import_plan(self, path_to_plan, **kwargs):
        overwrite = _bool_to_string_in_server_format(kwargs.pop('overwrite', False))
        with open(path_to_plan) as f:
            plan = f.read()
        self.api_client.api_operations_v1_execute_plan_import_post(body=plan, overwrite=overwrite, **kwargs)

