    @log_trigger_operation_data
    def reset_network_elements_password(self, *password_reset_args):
        network_elements = []
        for args in password_reset_args:
            if isinstance(args, dict):
                attrs = PasswordChangeNEAttributes(integrated_element_id=args.get('element_id'),
                                                   username=args.get('username'),
                                                   password=args.get('password'),
                                                   account_type=args.get('account_type'))
                network_elements.append(attrs)
            else:
                raise AttributeError("Attribute list should contain only dict objects.")
        reset_password_operation_start_object = ResetPasswordOperationStartObject(
            operation_attributes=PasswordChangeAttributes(
                network_elements=network_elements
            )
        )
        return self.api_client.reset_network_elements_password(
            reset_password_operation_start_object=reset_password_operation_start_object)

